def action_map(arr):
  out={}
  for a in (arr or []):
    k=(a or {}).get('action_type'); v=(a or {}).get('value')
    if not k or v is None: continue
    try: out[k]=out.get(k,0.0)+float(v)
    except Exception: pass
  return out

def cast_float(x,d=0.0):
  try: return float(x)
  except Exception: return d
